"""Offline source-paired sailboat player; build after the integrated renderer."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'integrated'
s=json.loads((OUT/'shot.json').read_text());checks=json.loads((OUT/'assembly-checks.json').read_text());tr=checks['trace_fidelity'];fit=checks['mask_fit'];n=len(s['keys'])
cards=[]
for k,f in enumerate(s['keys'],1):
 t=s['frames'][f]['source_time'];note=s['xsheet'][f]['note'];cards.append(f'<figure><div class="pair"><a href="source-{k:02d}.jpg"><img src="source-{k:02d}.jpg" alt="Archive at {t:.3f} seconds"></a><a href="key-{k:02d}.png"><img src="key-{k:02d}.png" alt="Native doodle key {k}"></a></div><figcaption>Key {k} · source {t:.3f} s · frame {f}<br>{escape(note)}</figcaption></figure>')
reviews=sorted(OUT.glob('review-v*.json'));reviewlink=f'<a href="{reviews[-1].name}">Independent still review</a> · 'if reviews else''
gap=s.get('review_note','Independent still and motion review pending.')
if not fit['pass_gate']:gap+=f' Filled boat/SAM fit fails: mean {fit["mean"]:.3f} against bar 0.65, minimum {fit["minimum"]:.3f} against bar 0.45.'
trace_note=('PASS'if tr['pass_gate']else'FAIL')+f': trace recall {tr["min_recall"]:.4f} / bar 0.98; parts kept {tr["min_parts_kept"]:.3f}.'
fit_note=('PASS'if fit['pass_gate']else'FAIL')+f': filled native boat / SAM IoU mean {fit["mean"]:.3f}, min {fit["minimum"]:.3f}; bars 0.65 / 0.45. Partial SAM target is not ground truth.'
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sailboat · assembled review · Secondhand Motion</title><link rel="icon" href="../../../favicon.svg"><style>
*{box-sizing:border-box}body{margin:0;background:#f5f1e8;color:#171512;font:17px/1.5 system-ui,sans-serif}main{max-width:1080px;margin:auto;padding:22px}a{color:inherit}nav,.tabs{display:flex;gap:12px 22px;flex-wrap:wrap}nav,.meta{font-size:14px}.meta{color:#625b50}h1{font-size:clamp(34px,7vw,64px);line-height:1.05;margin:28px 0 14px}.badge{display:inline-block;font-size:12px;font-weight:750;background:#ef9f3a;padding:5px 10px}.gap{border-left:4px solid #ef9f3a;background:#fffdf7;padding:10px 14px;font-size:15px}video{width:100%;display:block;background:#fffdf7;max-height:70vh;border:1px solid #d5caba;border-radius:7px}.tabs{margin:14px 0}button{font:inherit;padding:9px 14px;border:1px solid #b4a994;border-radius:5px;background:#fffdf7;color:inherit;cursor:pointer}button[aria-pressed=true]{background:#171512;color:#fffdf7}.keys{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.pair>*{min-width:0}.pair img{width:100%;display:block}figure{margin:0;border:1px solid #d5caba;border-radius:6px;overflow:hidden;background:#fffdf7}figcaption{padding:10px;font-size:13px}summary{cursor:pointer}details{margin:24px 0}details p{overflow-wrap:anywhere}footer{margin-top:30px;border-top:1px solid #d5caba;padding-top:15px;font-size:14px}@media(max-width:600px){main{padding:14px}.keys{grid-template-columns:1fr}button{font-size:15px;padding:9px 11px}}
</style><main><nav><a href="../../../index.html">Secondhand Motion</a><a href="../../moving-drawings.html">All moving drawings</a></nav><h1>Sailboat coming alongside.</h1><p class="meta">'''+str(n)+''' integrated keys · '''+str(s['frame_count'])+''' rendered frames · 24 fps · '''+f'{s["duration"]:.3f}'+''' seconds</p><p><span class="badge">ASSEMBLED REVIEW COPY · MOTION UNAPPROVED</span></p><p class="gap">'''+escape(gap)+'''</p><video id="film" controls playsinline preload="metadata" poster="poster.png" src="cartoon.mp4"></video><div class="tabs" aria-label="View"><button data-src="cartoon.mp4" data-poster="poster.png" aria-pressed="true">Cartoon</button><button data-src="comparison.mp4" data-poster="comparison-poster.jpg" aria-pressed="false">Source beside cartoon</button><button data-src="source-excerpt.mp4" data-poster="source-01.jpg" aria-pressed="false">Source</button></div><p class="meta">'''+escape(s['assembly_summary'])+'''</p><h2>The source and its keys</h2><section class="keys">'''+''.join(cards)+'''</section><details><summary>Source, doodle and checks</summary><p>One real Quick, Draw! sailboat, key 5193394433294336, retains its four source strokes and point correspondence. Quick, Draw! contributors / Google Creative Lab, CC BY 4.0. Far vessels, water contours and the trailing dinghy were drawn by agent from source observations. Reflected ink is an approximation.</p><p><a href="design.png"><img src="design.png" alt="Original Quick, Draw! sailboat" style="display:block;width:100%;max-width:420px"></a></p><p>Archive: <a href="'''+escape(s['source']['shot_page_url'])+'''">Dordrecht (1926)</a>. Retained clip-relative 3–9 s; reported public domain, as recorded by the archive. A title card and later cut are outside this interval.</p><p>'''+escape(trace_note)+'''<br>'''+escape(fit_note)+'''</p><p>Recognition/classifier and normal-speed independent playback are unrun. No planted intervals were independently observed; the minimum-four foot-contact gate is not passed. No training ran.</p><p><a href="shot.json">Editable timeline and strokes</a> · <a href="source.json">Source record</a> · <a href="source-contact-sheet.jpg">Source contact sheet</a> · <a href="assembly-checks.json">Checks</a> · '''+reviewlink+'''<a href="traced.json">Character traces</a> · <a href="correspondence.json">Native stroke correspondence</a> · <a href="sam/audit.jpg">SAM audit</a> · <a href="sam/provenance.json">Mask provenance</a></p></details><footer><a href="cartoon.mp4" download>Download cartoon</a> · <a href="comparison.mp4" download>Download comparison</a></footer></main><script>
const v=document.querySelector('#film');let generation=0;for(const b of document.querySelectorAll('button[data-src]'))b.addEventListener('click',()=>{const seq=++generation,t=v.currentTime,playing=!v.paused;for(const x of document.querySelectorAll('button[data-src]'))x.setAttribute('aria-pressed',String(x===b));v.pause();v.poster=b.dataset.poster;v.src=b.dataset.src;v.addEventListener('loadedmetadata',()=>{if(seq!==generation)return;v.currentTime=Math.min(t,Math.max(0,v.duration-.001));if(playing)v.play().catch(()=>{})},{once:true});v.load()});
</script></html>'''
(OUT/'index.html').write_text(html)
